	["Він більше не владний з мене. Мій погляд знову ясний. Дякую вам, герої."] = "Он больше не властен надо мной. Мой взор снова ясен. Благодарю вас, герои.",
	["Гаккар більше не владний наді мною! Нарешті я знайшов спокій!"] = "Хаккар больше не властен надо мной! Наконец-то я обрел покой!",
	["Гей! Гей ти, ззаду! Я за тобою стежу, то й знай!"] = "Эй! Эй ты, сзади! Я за тобой слежу, так и знай!",
	["Гей, хлопці, тут треба дещо налаштувати!"] = "Эй, ребята, тут надо кое-что настроить!",
	["Гербовая накидка Тайной магии"] = "Гербова накидка Таємної магії",
	["Геть, жалюгідний ельф. Настав мій час!"] = "Прочь, жалкий эльф. Настало мое время!",
	["Година відплати близька! Хай охопить морок серця наших ворогів!"] = "Час возмездия близок! Да охватит мрак сердца наших врагов!",
	["Головні ворота фортеці Альянсу зруйновані!"] = "Главные врата крепости Альянса разрушены!",
	["Головні ворота фортеці Орди зруйновані!"] = "Главные врата крепости Орды разрушены!",
	["Горе вам, усім і кожному, мої крихти!"] = "Горе вам, всем и каждому, мои крошки!",
	["Готова ще одна сфера! Поспішайте!"] = "Готова еще одна сфера! Торопитесь!",
	["Да начнется сражение за Берег Древних!"] = "Хай почнеться бій за Берег Стародавніх!",
	["Давні, дайте мені сили!"] = "Древни, дайте мне силы!",
	["Дайте час підготувати гармати."] = "Дайте время подготовить пушки.",
	["До початку бою за Альтеракську долину залишається 1 хвилина."] = "До начала сражения за Альтеракскую долину остается 1 минута.",
	["Добре. Воїни крижаних пусток, встаньте! Наказую вам боротися, вбивати і вмирати в ім'я свого повелителя! Не щадити нікого!"] = "Хорошо. Воины ледяных пустошей, восстаньте! Повелеваю вам сражаться, убивать и умирать во имя своего повелителя! Не щадить никого!",
	["Довгоног"] = "Долгоног",
	["Допоможіть мені, мої діти!"] = "Помогите мне, дети мои!",
	["Досить! Я зійду на землю і сам роздавлю тебе!"] = "Довольно! Я сойду на землю и сам раздавлю тебя!",
	["Другий раунд бою за Берег Стародавніх розпочнеться за 1 хвилину."] = "Второй раунд сражения за Берег Древних начнется через 1 минуту.",
	["Другий раунд починається за 30 секунд. Приготуйтеся!"] = "Второй раунд начинается через 30 секунд. Приготовьтесь!",
	["Друїди та їхні безглузді перетворення... Ну що ж, подивимось!"] = "Друиды и их дурацкие превращения... Ну что ж, поглядим!",
	["Дурні смертні. Думали, що здолали нас? Сан'лейн - непереможні воїни Короля-ліча. Тепер наші сили єдині!"] = "Глупые смертные. Думали, что одолели нас? Сан'лейн – непобедимые воины Короля-лича. Теперь наши силы едины!",
	["Дурні! Час – це вогонь, що спалює вас!"] = "Глупцы! Время – это огонь, сжигающий вас!",
	["Духи ветра станут вашей погибелью!"] = "Духи вітру стануть вашою смертю!",
	["Дякую, друзі! Завдяки вам я отримав найціннішу інформацію! Так, а куди ж я діл... - ах, куди."] = "Спасибо, друзья! Благодаря вам я получил ценнейшие сведения! Так, а куда же я дел... – ах, вот куда.",
	["Енергія. Сила. Мої люди без них не можуть... Ця залежність виникла після знищення Сонячної Криниці. Ласкаво просимо... у майбутнє. Мені дуже шкода, але ви не зможете нічого змінити. Тепер мене ніхто не зупинить! Селама ашаль-аноре!"] = "Энергия. Сила. Мои люди без них не могут... Эта зависимость возникла после уничтожения Солнечного Колодца. Добро пожаловать... в будущее. Мне очень жаль, но вы не сможете ничего изменить. Теперь меня никто не остановит! Селама ашаль-аноре!",
	["Еонар, твоїй служниці потрібна допомога!"] = "Эонар, твоей прислужнице нужна помощь!",
	["Жерці! Якщо ви збираєтеся так лікувати, то давайте хоч трохи урізноманітним процес!"] = "Жрецы! Если вы собираетесь продолжать так лечить, то давайте хоть немного разнообразим процесс!",
	["Живі? Тут?"] = "Живые? Здесь?!",
	["З найглибших і темніших печер Грозової Гряди був покликаний Гормок Пронизливий Бівень! У бій, герої!"] = "Из самых глубоких и темных пещер Грозовой Гряды был призван Гормок Пронзающий Бивень! В бой, герои!",
	["За Искусителя! За Кил'джедена!"] = "За Спокусника! За Кіл'джедена!",
	["За Легион! За Кил'джедена!"] = "За Легіон! За Кіл'джедена!",
	["Запускайте двигуни! Летимо назустріч долі."] = "Запускайте двигатели! Летим навстречу судьбе.",
	["Зараз великий чаклун Вілфред Непопамс закличе вашого нового супротивника. Готуйтесь до бою!"] = "Сейчас великий чернокнижник Вилфред Непопамс призовет вашего нового противника. Готовьтесь к бою!",
	["Зараз ви відповісте перед Саурфангом!"] = "Сейчас вы ответите перед Саурфангом!",
	["Захищайте мене! Швидше, будьте ви прокляті!"] = "Защищайте меня! Быстрее, будьте вы прокляты!",
	["Західна брама фортеці Альянсу зруйнована!"] = "Западные врата крепости Альянса разрушены!",
	["Західні ворота фортеці Орди зруйновані!"] = "Западные врата крепости Орды разрушены!",
	["Згадайте, чого я вас навчав!"] = "Вспомните, чему я вас учил!",
	["Земля починає розколюватись!"] = "Земля начинает раскалываться!",
	["Зі смертю ми давно вже друзі ... Що чекає тепер на пустки мене?"] = "Со смертью мы давно уже друзья...Что ждет теперь на пустоши меня?",
	["Иллидан Ярость Бури."] = "Іллідан Лють Бурі.",
	["Как долго вы сможете сопротивляться?"] = "Як довго ви зможете чинити опір?",
	["Каперніан простежить, щоб ви не затрималися надовго."] = "Каперниан проследит, чтобы вы не задержались здесь надолго.",
	["Кел'Тузад оголосив Лоскутика втіленням війни!"] = "Кел'Тузад объявил Лоскутика воплощением войны!",
	["Кил'джедена надо уничтожить!"] = "Кіл'джедена треба знищити!",
	["Ким би мені тут закусити?"] = "Кем бы мне тут закусить?",
	["Клаптик хоче пограти!"] = "Лоскутик хочет поиграть!",
	["Кологарн спрямовує на вас свій погляд!"] = "Кологарн устремляет на вас свой взгляд!",
	["Корабель під обстрілом! Бойового мага сюди, хай заткне ці гармати!"] = "Корабль под обстрелом! Боевого мага сюда, пусть заткнет эти пушки!",
	["Корабель під обстрілом! Заклинача сюди, хай заткне ці гармати!"] = "Корабль под обстрелом! Заклинателя сюда, пусть заткнет эти пушки!",
	["Король-ліч ПАДЕ!"] = "Король-лич ПАДЕТ!",
	["Король-ліч зазнав важкої втрати! Ви виявили себе як безстрашні герої Срібного Авангарду! Ми разом завдамо удару по Цитаделі Крижаної Корони і рознесемо на шматки залишки Скари! Немає такого випробування, яке ми не могли б пройти спільно!"] = "Король-лич понес тяжелую потерю! Вы проявили себя как бесстрашные герои Серебряного Авангарда! Мы вместе нанесем удар по Цитадели Ледяной Короны и разнесем в клочья остатки Плети! Нет такого испытания, которое мы бы не могли пройти сообща!",
	["Король-ліч поглине всі..."] = "Король-лич поглотит все...",
	["Критичне значення рівня небезпеки. Перенаправлення аналізу Безодні. Ініціювання протоколу очищення."] = "Критическое значение уровня угрозы. Перенаправление анализа Бездны. Инициирование протокола очищения.",
	["Кричіть! Кричіть щосили!"] = "Кричите! Кричите изо всех сил!",
	["Кто такой этот Всадник без головы?"] = "Хто такий цей Вершник без голови?",
	["Лава навколо |3-1(%s) починає вирувати!"] = "Лава вокруг |3-1(%s) начинает бурлить!",
	["Левая рука отросла заново!"] = "Ліва рука відросла заново!",
	["Леди Джайна Праудмур хочет видеть тебя немедленно."] = "Леді Джайна Праудмур хоче бачити тебе негайно.",
	["Лицарі смерті! Сюди!"] = "Рыцари смерти! Сюда!",
	["Лише згуртувавшись, ви зможете пройти останнє випробування. З глибин Крижаної Корони назустріч вам піднімаються дві могутні воїнки Скари: моторошні валь'кіри, крилаті вісниці Короля-лича!"] = "Лишь сплотившись, вы сможете пройти последнее испытание. Из глубин Ледяной Короны навстречу вам подымаются две могучие воительницы Плети: жуткие валь'киры, крылатые вестницы Короля-лича!",
	["Лише тіло!"] = "Всего лишь плоть!",
	["Мал'Ганис заплатит за это."] = "Мал'Ганіс заплатить за це.",
	["Мене вистачить на вас!"] = "Меня на вас хватит!",
	["Мене так просто не візьмеш! Нехай стіни в'язниці здригнуться... і впадуть!"] = "Меня так просто не возьмешь! Пусть стены темницы содрогнутся... и падут!",
	["Меня схватили!"] = "Мене схопили!",
	["Мені відкриті всі реальності, всі виміри!"] = "Мне открыты все реальности, все измерения!",
	["Мені дуже потрібне серце. Може, забрати твоє?"] = "Мне очень нужно сердце. Может, забрать твое?",
	["Меч ніхто не стереже? Не може бути!"] = "Меч никто не охраняет? Не может быть!",
	["Ми незліченні, як зірки! Ми заполонимо всесвіт!"] = "Мы бесчисленны, как звезды! Мы заполоним вселенную!",
	["Ми прорвалися через тюремні ворота! Дорога до Даларану відкрита! Тепер ми нарешті припинимо війну Нексуса!"] = "Мы прорвались через тюремные ворота! Дорога в Даларан открыта! Теперь мы наконец прекратим войну Нексуса!",
	["Мисливці зі своїми жалюгідними пугачами!"] = "Охотники со своими жалкими пугачами!",
	["Можливо, я вас недооцінив. Було б несправедливо змушувати вас битися з чотирма радниками одразу, але... Мої люди теж ніколи не знали справедливості. Я лише повертаю борг."] = "Возможно, я недооценил вас. Было бы несправедливо заставлять вас драться с четырьмя советниками сразу, но... Мои люди тоже никогда не знали справедливости. Я лишь возвращаю долг.",
	["Мои спутники и я – с вами, леди Праудмур."] = "Мої супутники і я з вами, леді Праудмур.",
	["Мой ответ – Кил'джеден."] = "Моя відповідь – Кіл'джеден.",
	["Моліть про пощаду!"] = "Молите о пощаде!",
	["Моліть про пощаду! Незабаром ваше мізерне існування закінчиться!"] = "Молите о пощаде! Вскоре ваше ничтожное существование закончится!",
	["Моя поразка лише наблизить вашу смерть."] = "Мое поражение лишь приблизит вашу погибель.",
	["Мій обов'язок – оберігати ці яйця, і ви згорите, перш ніж хоч пальцем чіпатиме їх!"] = "Моя обязанность – оберегать эти яйца, и вы сгорите, прежде чем хоть пальцем тронете их!",
	["Мій пане! Я зробила, як ви наказали, і тепер благаю вас про благословення!"] = "Мой господин! Я сделала, как вы велели, и теперь молю вас о благословении!",
	["Мій терпець урвався! Час вас позбутися!"] = "Мое терпение лопнуло! Пора от вас избавиться!",
	["На вас чекає безодня безумства!"] = "Вас ждет бездна безумия!",
	["На жаль, безстрашні герої ваша нав'язливість прискорила розв'язку. Ви чуєте гуркіт кісток і скрегіт стали за вашими спинами? Це провісники швидкої смерті."] = "Увы, бесстрашные герои, ваша навязчивость ускорила развязку. Вы слышите громыхание костей и скрежет стали за вашими спинами? Это предвестники скорой погибели.",
	["На жаль, іноді доводиться брати все у свої руки. Баламоре шаналь!"] = "Увы, иногда приходится брать все в свои руки. Баламоре шаналь!",
	["На колени!! Склонитесь пред клыком и когтем!"] = "На коліна!! Схилиться перед іклом і пазуром!",
	["На смак, як вишенька! ОЙ! Вибачте!"] = "На вкус, как вишенка! ОЙ! Извиниите!",
	["На это... я... не рассчитывала..."] = "На це... я... не розраховувала...",
	["Навчання закінчено! Покажіть мені, що ви засвоїли!"] = "Обучение окончено! Покажите мне, что вы усвоили!",
	["Надія – це ХВОРОБА душі! Ця земля зачахне та помре!"] = "Надежда – это БОЛЕЗНЬ души! Эта земля зачахнет и умрет!",
	["Назгрім: Земля? Тут? Не може бути!"] = "Назгрим: Земля? Здесь? Не может быть!",
	["Нам нечего бояться."] = "Нам нема чого боятися.",
	["Нарешті моє ув'язнення закінчено!"] = "Наконец-то мое заточение окончено!",
	["Нарешті я... вільний від його кайданів..."] = "Наконец-то я... свободен от его оков...",
	["Настирна тварюка! Я сам тебе вб'ю!"] = "Настырная тварь! Я сам тебя убью!",
	["Нахабні цуценята! Ви самі прирекли себе на смерть! Побачте ж Повелителя в гніві!"] = "Нахальные щенки! Вы сами обрекли себя на смерть! Узрите же Повелителя в гневе!",
	["Не може бути!"] = "Не может быть!",
	["Не може бути! Встаньте, мої прислужники! Послужіть пану ще раз!"] = "Не может быть! Восстаньте, мои прислужники! Послужите господину еще раз!",
	["Не може бути! Це не закінчиться так!"] = "Не может быть! Это не закончится вот так!",
	["Не може бути... Інею... Попередь..."] = "Не может быть... Иней... Предупреди...",
	["Не набридло ще тікати?"] = "Не надоело еще убегать?",
	["Небеса у вогні!"] = "Небеса в огне!",
	["Невже ви не розумієте всієї марності того, що відбувається?"] = "Неужели вы не понимаете всей бесполезности происходящего?",
	["Невже прибули нарешті хвалені сили Світла? Мені кинути Крижану Скорботу і здатися на твою милість, Фордрінг?"] = "Неужели прибыли наконец хваленые силы Света? Мне бросить Ледяную Скорбь и сдаться на твою милость, Фордринг?",
	["Непогано, тепер ви можете потягатися з головним інженером Телонікусом."] = "Неплохо, теперь вы можете потягаться с моим главным инженером Телоникусом.",
	["Непрохані гості! Ви заплатите за те, що посміли втрутитися... Стривайте, ви..."] = "Незваные гости! Вы заплатите за то, что посмели вмешаться... Погодите, вы...",
	["Нехай змагання розпочнуться!"] = "Пусть состязания начнутся!",
	["Нехай наші вороги тремтять! Смерть їм!"] = "Пусть наши враги трепещут! Смерть им!",
	["Нещасні сліпі дурні!"] = "Несчастные слепые глупцы!",
	["Низина Арати"] = "Низина Араті",
	["Ну а тепер, покінчимо з цим!"] = "Ну а теперь, покончим с этим!",
	["Ну, не говоріть потім, що я не попереджав. В атаку, брати та сестри!"] = "Ну не говорите потом, что я не предупреждал. В атаку, братья и сестры!",
	["Ні! Будь проклята ця жалюгідна смертна оболонка!"] = "Нет! Будь проклята эта жалкая смертная оболочка!",
	["Ні! Не може бути! Ти мене не зупиниш!"] = "Нет! Не может быть! Ты меня не остановишь!",
	["Ні! Я зможу це зробити... я зможу..."] = "Нет! Я смогу это сделать... я смогу...",
	["Ні! Я не можу… знову… програти."] = "Нет! Я не могу... снова... проиграть.",
	["Ні... ні! Що ви наробили? Я головний! Чуєш мене? Я... Ааааах! Мені його... не втримати."] = "Нет... нет! Что вы наделали? Я – главный! Слышишь меня? Я... Ааааах! Мне его... не удержать.",
	["Нікчеми! Я вам покажу мою силу!"] = "Ничтожества! Я вам покажу мою силу поближе!",
	["Нікчемні лакеї! Ваші трупи стануть гарною закускою для мого нового дракона!"] = "Ничтожные лакеи! Ваши трупы послужат хорошей закуской для моего нового дракона!",
	["Ніхто не перевершить силу шторму."] = "Никто не превзойдет силу шторма.",
