	["Облоговий танк вибухає!"] = "Осадный танк взрывается!",
	["Огненный Левиафан начинает испытывать перегрузку!"] = "Вогняний Левіафан починає зазнавати перевантаження!",
	["Одна хвилина на початок бою на арені!"] = "Одна минута до начала боя на арене!",
	["Оленя Шлем буде скиглити і благати про пощаду, точно як його сопливий синок! Тисячолітня несправедливість сьогодні скінчиться!"] = "Олений Шлем будет скулить и молить о пощаде, в точности как его сопливый сынок! Тысячелетняя несправедливость сегодня закончится!",
	["Они пришли. Постарайся не дать себя убить, юноша."] = "Вони прийшли. Постарайся не дати себе вбити, юнак.",
	["Осадная машина готова к бою!"] = "Облогова машина готова до бою!",
	["Оце сюрприз. Зазвичай, щоб знайти обід, мені доводиться залишати лігво."] = "Вот это сюрприз. Обычно, чтобы найти обед, мне приходится покидать логово.",
	["Очевидно, я зробив невелику помилку у розрахунках. Полонений лиходій затуманив мій розум і змусив мене відхилитися від інструкцій. Нині всі системи в нормі. Кінець зв'язку."] = "Очевидно, я совершил небольшую ошибку в расчетах. Пленный злодей затуманил мой разум и заставил меня отклониться от инструкций. Сейчас все системы в норме. Конец связи.",
	["П'ятнадцять секунд до початку бою на арені!"] = "Пятнадцать секунд до начала боя на арене!",
	["ПЕРЕВІДНО! Просто чудовий результат! Цілісність обшивки – 98,9 відсотка! Майже що не подряпини! Продовжуємо!"] = "ПРЕВОСХОДНО! Просто восхитительный результат! Целостность обшивки – 98,9 процента! Почти что ни царапинки! Продолжаем!",
	["Паладини... Я чув, у вас є кілька життів. Доведіть."] = "Паладины... Я слышал, у вас несколько жизней. Докажите.",
	["Пане, мені потрібна допомога!"] = "Господин, мне нужна помощь!",
	["Персонажи, несущие флаг, стали еще более уязвимы!"] = "Персонажі, які несуть прапор, стали ще вразливішими!",
	["Персонажі, які несуть прапор, стали вразливішими!"] = "Персонажи, несущие флаг, стали более уязвимы!",
	["Побачте чудо творення!"] = "Узрите чудо созидания!",
	["Побе-еда! Мы справились!"] = "Перемога! Ми впоралися!",
