	["Победа!!! Победы Орды!"] = "Перемога! Перемоги Орди!",
	["Поблизу починають виникати саронітові випари!"] = "Поблизости начинают возникать саронитовые испарения!",
	["Повстань і набуди справжньої форми!"] = "Восстань и обрети истинную форму!",
	["Погляньте на світ моїми очима: побачіть неосяжний всесвіт, незбагненний навіть для найбільших розумів."] = "Взгляните на мир моими глазами: узрите необъятную вселенную, непостижимую даже для величайших умов.",
	["Подивимося які ви на смак!"] = "Посмотрим, какие вы на вкус!",
	["Подряпина..."] = "Царапина...",
	["Покажіть мені, що здатні!"] = "Покажите мне, на что способны!",
	["Поки я дихаю, вам не досягти свого!"] = "Пока я дышу, вам не добиться своего!",
	["Покоритесь леденящей смерти!"] = "Підкоріться смерті, що леденить!",
	["Полководец Калитреш падет!"] = "Полководець Калітреш впаде!",
	["Полководец Калитреш услышит об этой наглости!"] = "Полководець Калітреш почує про це нахабство!",
	["Порог допустимої загрози перевищено. Астрономічний архів вимкнено. Рівень безпеки підвищено."] = "Порог допустимой угрозы превышен. Астрономический архив отключен. Уровень безопасности повышен.",
	["Порожня та гірка перемога. Після сьогоднішніх втрат ми стали слабшими як ціле. Хто ще, крім Короля-лича, виграє від подібної дурниці? Впали великі воїни. І заради чого? Справжня небезпека ще попереду – на нас чекає битва з Королем-личом."] = "Пустая и горькая победа. После сегодняшних потерь мы стали слабее как целое. Кто еще, кроме Короля-лича, выиграет от подобной глупости? Пали великие воины. И ради чего? Истинная опасность еще впереди – нас ждет битва с Королем-личом.",
	["Потрібно захистити Оранжерею!"] = "Нужно защитить Оранжерею!",
	["Появляется электрическая буря!"] = "Виникає електрична буря!",
	["Правая рука отросла заново!"] = "Права рука відросла заново!",
	["Приготуйтеся до бою з близнюками-жахливими, Кислотною Утробою і Моторошною Лускою!"] = "Приготовьтесь к схватке с близнецами-чудовищами, Кислотной Утробой и Жуткой Чешуей!",
	["Прийди ж, ласкава ніч, поверни мені мого Ромуло!"] = "Приди же, ласковая ночь, верни мне моего Ромуло!",
	["Прийдіть, МОЇ СЛУГИ! ЗАХИСТІТЬ СВОГО ГОСПОДАРЯ!"] = "ПРИДИТЕ, МОИ СЛУГИ! ЗАЩИТИТЕ СВОЕГО ХОЗЯИНА!",
	["Применение"] = "Застосування",
	["Применяй \"Ледяное дыхание\", бестолочь!"] = "Застосовуй \"Крижане дихання\", безглуздя!",
	["Притримайте мечі! Я здаюсь."] = "Придержите мечи! Я сдаюсь.",
	["Проекція |3-1(%s) вибухає!"] = "Проекция |3-1(%s) взрывается!",
	["Профессор Мерзоцид отменил действие мутации!"] = "Професор Мерзоцид скасував дію мутації!",
	["Профессор Мерзоцид произносит заклинание |cFF00FF00\"Вязкая гадость\"!|r"] = "Професор Мерзоцид вимовляє заклинання |cFF00FF00\"В'язка гидота\"!|r",
	["Прочь, подлецы! Альтеракская долина достанется Альянсу!"] = "Геть, негідники! Альтеракська долина дістанеться Альянсу!",
	["Пусть сражение за Берег Древних начнется!"] = "Нехай бій за Берег Стародавніх розпочнеться!",
	["Підведіться, сини та дочки Орди! Сьогодні ми битимемося зі смертельним ворогом! ЛОК'ТАР ОГАР!"] = "Воспряньте, сыны и дочери Орды! Сегодня мы будем биться со смертельным врагом! ЛОК'ТАР ОГАР!",
	["Після цього нічого не лишиться!"] = "После этого ничего не останется!",
	["Піхота, сержанти, у бій!"] = "Пехота, сержанты, в бой!",
	["Розбійники? Досить ховатися, здайтеся!"] = "Разбойники? Хватит прятаться, покажитесь!",
	["Розшифруйте це!"] = "Расшифруйте вот это!",
	["Руйнівники, сержанти, у бій!"] = "Разрушители, сержанты, в бой!",
	["Сапфірон відновлює свою атаку!"] = "Сапфирон возобновляет свою атаку!",
	["Сапфірон злітає у повітря!"] = "Сапфирон взмывает в воздух!",
	["Сатроварр Поширювач Скверни."] = "Сатроварр Осквернитель.",
	["Світ – це лише швидкоплинний сон. Нехай править КОШМАР!"] = "Мир – это всего лишь мимолетный сон. Пусть правит КОШМАР!",
	["Сильний поштовх землетрусу насторожив мурлок поблизу!"] = "Сильный толчок землетрясения насторожил мурлоков поблизости!",
	["Скади Безжалостный в пределах досягаемости пусковых установок гарпунов!"] = "Скаді Безжальний в межах досяжності пускових установок гарпунів!",
	["Скоро ми битимемося з ватажком цих нелюдів! Зверніть гнів і ненависть проти його прислужників!"] = "Скоро мы сразимся с главарем этих извергов! Обратите гнев и ненависть против его прислужников!",
	["Скоріше нападемо на них ззаду!"] = "Скорей, нападем на них сзади!",
	["Слишком поздно..."] = "Надто пізно...",
	["Слуги! Зверніть їх у попіл!"] = "Слуги! Обратите их в пепел!",
	["Смерть чужинцям!"] = "Смерть чужакам!",
	["Смерть чужинцям! Ніхто не сміє втручатися у справи культу!"] = "Смерть чужакам! Никто не смеет вмешиваться в дела культа!",
	["Смотритель стойл"] = "Доглядач стійл",
	["Соратники, слуги, солдаты холодной тьмы! Повинуйтесь зову Кел'Тузада!"] = "Соратники, слуги, солдати холодної пітьми! Коріться поклику Кел'Тузада!",
	["Спадщина бур не помре разом зі мною."] = "Наследие бурь не умрет вместе со мной.",
	["Сражение за Берег Древних завершилось!"] = "Бій за Берег Стародавніх завершився!",
	["Сталагг скрушити вас!"] = "Сталагг сокрушить вас!",
	["Стародавня істота прокидається вдалині."] = "Древнее существо пробуждается вдалеке...",
	["Стережіться тіней!"] = "Остерегайтесь теней!",
	["Супремус атакує нову мету!"] = "Супремус атакует новую цель!",
	["Сфера вибухає!"] = "Сфера взрывается!",
	["Схоже, вам потрібно подати ще один урок, смертні!"] = "Похоже, вам требуется преподать еще один урок, смертные!",
	["Схоже, всі готові. Пам'ятайте, ці люди заражені чумою і скоро помруть. Ми повинні очистити Стратгольм і захистити Лордерон від Скари. Уперед."] = "Похоже, все готовы. Помните, эти люди заражены чумой и скоро умрут. Мы должны очистить Стратхольм и защитить Лордерон от Плети. Вперед.",
	["Східні ворота фортеці Альянсу зруйновані!"] = "Восточные врата крепости Альянса разрушены!",
	["Східні ворота фортеці Орди зруйновані!"] = "Восточные врата крепости Орды разрушены!",
	["Сьогодні... ми побачимо історію кохання!"] = "Сегодня... мы увидим историю любви!",
	["ТИ НЕ МОЖЕШ ПЕРЕМОГТИ ЖИВУ СПЕКУ! ПРИДІТЬ, СЛУГИ ВОГНЮ! ПРИЙДІТЬ, ТВОРЕННЯ НЕНАВИСТИ! ВАШ ПАН ПРИЗИВАЄ ВАС!"] = "ТЫ НЕ МОЖЕШЬ ПОБЕДИТЬ ЖИВОЙ ЖАР! ПРИДИТЕ, СЛУГИ ОГНЯ! ПРИДИТЕ, ТВОРЕНИЯ НЕНАВИСТИ! ВАШ ГОСПОДИН ПРИЗЫВАЕТ ВАС!",
	["Таких, як ви, тут не повинно бути! Смерть загрожує лише вам!"] = "Таких, как вы, здесь быть не должно! Смерть грозит лишь вам!",
	["Твоя подорож починається, молодий принц. Збирай свої війська і вирушай у царство вічних снігів, до Нордсколу. Там ми й залагодимо всі наші справи, там ти дізнаєшся про свою долю."] = "Твое путешествие начинается, юный принц. Собирай свои войска и отправляйся в царство вечных снегов, в Нордскол. Там мы и уладим все наши дела, там ты узнаешь свою судьбу.",
	["Телепортация к пушке будет стоить:"] = "Телепортація до гармати коштуватиме:",
	["Тепер будьте уважні! Не встигнете й оком моргнути, як..."] = "Теперь будьте внимательны! Не успеете и глазом моргнуть, как...",
	["Тепер ви належите мені!"] = "Теперь вы принадлежите мне!",
	["Тепер твоя душа пов'язана із моєю!"] = "Теперь твоя душа связана с моей!",
	["Терон Кровожад."] = "Терон Кровожер.",
	["Терон Кровожад? Да... я знаю его."] = "Терон Кровожер? Так... я його знаю.",
	["Тобі не втекти!"] = "Тебе не уйти!",
	["Тридцять секунд до початку бою на арені!"] = "Тридцать секунд до начала боя на арене !",
	["Труп будить!"] = "Труп бдыжь!",
	["Тут ваше вторгнення і скінчиться! Ніхто не вціліє."] = "Здесь ваше вторжение и окончится! Никто не уцелеет.",
	["Ті, ким можна було пожертвувати, мертві. Тож тому й бути! Я досягну успіху там, де Саргерас зазнав поразки! Я примушу цей жалюгідний світ стікати кров'ю і навіки закріплю за собою місце повелителя Палаючого Легіону! Пробив останню годину цього світу!"] = "Те, кем можно было пожертвовать, мертвы. Так тому и быть! Я добьюсь успеха там, где Саргерас потерпел поражение! Я заставлю этот жалкий мирок истекать кровью и навеки закреплю за собой место повелителя Пылающего Легиона! Пробил последний час этого мира!",
	["Тіто, ми просто повинні знайти дорогу додому! Старий чарівник – наша єдина надія. Пугало, Ревун, Нержавію, ви... ой, до нас хтось прийшов!"] = "Тито, мы просто обязаны найти дорогу домой! Старый волшебник – наша единственная надежда. Пугало, Рычун, Нержавей, вы... ой, к нам кто-то пришел!",
	["У нас мало часу, друзі! Ви допоможете випробувати найновіший і найбільший з моїх винаходів. І врахуйте: після того, що ви наробили з XT-002, відмовлятися просто некрасиво."] = "У нас мало времени, друзья! Вы поможете испытать новейшее и величайшее из моих изобретений. И учтите: после того, что вы натворили с XT-002, отказываться просто некрасиво.",
	["У повітрі повіяло крижаним диханням наступного бійця: на арену виходить Крижаний Рев! Боріться чи загиніть, чемпіони!"] = "В воздухе повеяло ледяным дыханием следующего бойца: на арену выходит Ледяной Рев! Сражайтесь или погибните, чемпионы!",
	["У покої пана проникли!"] = "В покои господина проникли!",
	["У світі сутінків ви знайдете лише страждання! Заходьте, якщо посмієте!"] = "В мире сумерек вы найдете лишь страдания! Входите, если посмеете!",
	["У стіні пролом! Реліквії загрожує небезпека!"] = "В стене пролом! Реликвии грозит опасность!",
	["У сферах, що обертаються, пульсує темна енергія!"] = "Во вращающихся сферах пульсирует темная энергия!",
	["Увага: запобіжні заходи деактивовані. Починаю стирання пам'яті та..."] = "Внимание: меры предосторожности деактивированы. Начинаю стирание памяти и...",
	["Фазу попередньої перевірки завершено. Настав час почати головний тест!"] = "Фаза предварительной проверки завершена. Пора начать главный тест!",
	["Флаг возвращен на базу."] = "Прапор повернуто на базу.",
	["Флаг уронили!"] = "Прапор упустили!",
	["Фортеця атакують!"] = "Крепость атакуют!",
	["Ха-ха-ха! Ви безнадійно слабкі!"] = "Ха-ха-ха! Вы безнадежно слабы!",
	["Хм, щось я нічого не відчуваю. Що? Це ще звідки?"] = "Хм, что-то я ничего не чувствую. Что?! Это еще откуда?",
